create or replace function public.compute_bathroom_intelligence(p_location_id uuid) returns public.location_bathroom_intelligence language plpgsql security definer set search_path='public','extensions','auth','pg_temp' as $function$ declare v_category text; v_positive int:=0; v_negative int:=0; v_customers int:=0; v_permissive int:=0; v_public int:=0; v_community_pos int:=0; v_community_neg int:=0; v_evidence int:=0; v_pos boolean:=false; v_neg boolean:=false; v_access text:='unknown'; v_status text:='unknown'; v_prior numeric:=0; v_source numeric:=0; v_conf numeric:=0; v_fresh numeric:=100; v_row public.location_bathroom_intelligence; begin select lower(coalesce(place_type,'')) into v_category from public.locations where id=p_location_id;
select count(*) filter(where lower(coalesce(eo.value_text,'')) in('yes','true','1','vault')),count(*) filter(where lower(coalesce(eo.value_text,'')) in('no','false','0')),count(*) filter(where lower(coalesce(eo.attribute_key,'')) like '%toilets:access%' and lower(coalesce(eo.value_text,''))='customers'),count(*) filter(where lower(coalesce(eo.attribute_key,'')) like '%toilets:access%' and lower(coalesce(eo.value_text,''))='permissive'),count(*) filter(where lower(coalesce(eo.attribute_key,'')) like '%toilets:access%' and lower(coalesce(eo.value_text,''))='yes') into v_positive,v_negative,v_customers,v_permissive,v_public from public.external_observations eo where eo.location_id=p_location_id and lower(coalesce(eo.attribute_key,'')) like '%toilets%';
select count(*) filter(where observation_type in('clean','supplies_ok','open','accessible','changing_table','bathroom_present')),count(*) filter(where observation_type in('dirty','supplies_low','closed','not_accessible','no_changing_table','bathroom_missing')),coalesce(extract(epoch from (now()-max(created_at)))/86400,9999) into v_community_pos,v_community_neg,v_fresh from public.restroom_observations where location_id=p_location_id;
v_evidence:=v_positive+v_negative+v_customers+v_permissive+v_public+v_community_pos+v_community_neg; v_pos:=v_evidence>0 and v_positive+v_customers+v_permissive+v_public+v_community_pos>0; v_neg:=v_negative+v_community_neg>0;
v_prior:=case when v_category in('restaurant','gas_station','cafe','shopping','service','health','library','restroom','hotel','bar','fast_food') then 75 when v_category in('park','dog_park','public_safety','transit','travel') then 50 else 25 end;
v_source:=least(100,v_evidence*12.5); v_fresh:=greatest(0,least(100,100-(v_fresh*3.333333)));
if v_pos and v_neg then v_status:='uncertain'; elsif v_pos then v_status:='confirmed'; elsif v_neg then v_status:='no_bathroom'; elsif v_prior>=75 then v_status:='likely'; elsif v_prior>=50 then v_status:='uncertain'; end if;
if v_customers>0 then v_access:='customers'; elsif v_public>0 then v_access:='public'; elsif v_permissive>0 then v_access:='permissive'; elsif v_neg and not v_pos then v_access:='none'; end if;
v_conf:=case when v_pos and v_neg then 60 when v_pos then least(99,80+v_source*.19) when v_neg then 95 when v_prior>=75 then v_prior else greatest(20,v_prior) end; v_conf:=greatest(0,least(99,v_conf*(0.5+0.5*v_fresh/100)));
insert into public.location_bathroom_intelligence as bi(location_id,status,access,confidence,evidence_count,explicit_positive,explicit_negative,category_prior,source_score,freshness_score,computed_at,updated_at) values(p_location_id,v_status,v_access,v_conf,v_evidence,v_pos,v_neg,v_prior,v_source,v_fresh,now(),now()) on conflict(location_id) do update set status=excluded.status,access=excluded.access,confidence=excluded.confidence,evidence_count=excluded.evidence_count,explicit_positive=excluded.explicit_positive,explicit_negative=excluded.explicit_negative,category_prior=excluded.category_prior,source_score=excluded.source_score,freshness_score=excluded.freshness_score,computed_at=excluded.computed_at,updated_at=now() returning * into v_row; return v_row; end $function$;
create or replace function public.refresh_restroom_observation_intelligence_trigger() returns trigger language plpgsql security definer set search_path='public','extensions','auth','pg_temp' as $function$ begin perform public.compute_bathroom_intelligence(coalesce(new.location_id,old.location_id)); return coalesce(new,old); end $function$;
drop trigger if exists restroom_observations_bathroom_intelligence on public.restroom_observations;
create trigger restroom_observations_bathroom_intelligence after insert or update or delete on public.restroom_observations for each row execute function public.refresh_restroom_observation_intelligence_trigger();
comment on function public.compute_bathroom_intelligence(uuid) is 'Canonical bathroom intelligence combines external amenity evidence with community restroom observations, contradiction state, and observation freshness.';
